/**
 * Checks if the given value is an array<string, bool>.
 *
 * @param mixed $value
 *   The value to check.
 *
 * @return bool
 *   TRUE if the given value is an array<string, bool>.
 *
 * @phpstan-assert-if-true array<string, bool> $value
 */
function isArrayStringBool(mixed $value): bool
{
    if (!is_array($value)) {
        return FALSE;
    }
    foreach ($value as $var1 => $var0) {
        if (
            !is_string($var1) ||
            !is_bool($var0)
        ) {
            return FALSE;
        }
    }
    return TRUE;
}

